 * Pour les classes ci-dessous, la liste vient de l'onglet « Liste <classe> » du tableur des résultats :
 * un élève par ligne en colonne A (« NOM Prénom », comme pour les Premières), « oui » en colonne B pour le tiers temps.
 * L'onglet est créé vide au premier passage ; une modification est prise en compte en deux minutes au plus. */
const LISTES_TABLEUR_ = ['Terminale ST2S'];
function listesTableur_() {
  const c = CacheService.getScriptCache(), v = c.get('LST');
  if (v) { try { return JSON.parse(v); } catch (e) {} }
  const o = { classes: {}, tiers: [] };
  LISTES_TABLEUR_.forEach(function (k) {
    try {
      const sh = onglet_('Liste ' + k, ['Nom et prénom (NOM Prénom)', 'Tiers temps (oui)']);
      const n = sh.getLastRow();
      if (n < 2) return;
      const L = [];
      sh.getRange(2, 1, Math.min(n - 1, 80), 2).getDisplayValues().forEach(function (r) {
        const nm = norm_(r[0]);
        if (!nm || L.indexOf(nm) >= 0) return;
        L.push(nm);
        if (/^\s*(oui|o|x|1|tt|vrai)\s*$/i.test(String(r[1] || ''))) o.tiers.push(nm);
      });
      if (L.length) o.classes[k] = L;
    } catch (e) {}
  });
  try { c.put('LST', JSON.stringify(o), 120); } catch (e) {}
  return o;
}
